sys_security_acl.script:
var userId = gs.getUserID();
var emp = current.getValue('employee');
var team = current.getValue('team');
var dept = current.getValue('department');

// Own profile
if (emp == userId) { answer = true; }
// Team member (same group)
else if (team && gs.getUser().isMemberOf(team)) { answer = true; }
// Team lead (manager of the profile's team)
else if (team && current.team.manager == userId) { answer = true; }
// Department head
else if (dept && current.department.dept_head == userId) { answer = true; }
else { answer = false; }
